python3 -c "
import json
d=json.load(open('/app/trial/agent/trajectory.json'))
steps=d['steps']
for i,s in enumerate(steps):
    msg = s.get('message')
    tc = s.get('tool_calls')
    obs = s.get('observation')
    print('=== STEP', i, s.get('timestamp'), '===')
    if msg:
        if isinstance(msg, str):
            print('MSG:', msg[:1500])
        else:
            print('MSG:', json.dumps(msg)[:1500])
    if tc:
        print('TOOL_CALLS:', json.dumps(tc)[:2000])
    if obs:
        print('OBS:', json.dumps(obs)[:1500])
    print()
"

